const now = new Date().toISOString();
console.log(`🔄 Infrastructure Setup and Validation Workflow started at ${now}`);

// Initialize tracking variables
return [{
  json: {
    timestamp: now,
    workflow_version: "1.0.0",
    validation_results: {
      database: {
        tables_checked: [],
        tables_created: [],
        columns_added: [],
        errors: []
      },
      s3: {
        bucket_exists: false,
        folders_checked: [],
        folders_created: [],
        errors: []
      }
    }
  }
}];

// Get existing tables from previous node
const existingTables = $input.all().map(item => item.json.table_name);

// Define required tables
const requiredTables = ['llm_analysis', 'calls', 'pipe_response', 'agent_results'];

// Find missing tables
const missingTables = requiredTables.filter(table => !existingTables.includes(table));

// Update validation results
const validationResults = $node['Workflow Initialization'].json.validation_results;
validationResults.database.tables_checked = requiredTables;

// Generate SQL for missing tables
let createTableSQL = '';

if (missingTables.includes('llm_analysis')) {
  createTableSQL += `
  CREATE TABLE IF NOT EXISTS public.llm_analysis (
    id SERIAL PRIMARY KEY,
    call_id VARCHAR(100) UNIQUE NOT NULL,
    sentiment VARCHAR(50),
    topic VARCHAR(200),
    significant_term VARCHAR(100),
    general_value VARCHAR(50),
    general_experience VARCHAR(50),
    email_inquired VARCHAR(10),
    positive_comment_passed_sale VARCHAR(10),
    negative_comment_passed_sale VARCHAR(10),
    price_negotiated VARCHAR(10),
    customer_addressed_politely VARCHAR(10),
    conversation_fun VARCHAR(10),
    service_advantages_mentioned VARCHAR(10),
    other_platforms_mentioned VARCHAR(10),
    sale_outcome VARCHAR(50),
    sale_value_scale INTEGER,
    asked_if_commenters_known VARCHAR(10),
    high_profile_advantages_mentioned VARCHAR(10),
    llm_error_message TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    analysis_method VARCHAR(50) DEFAULT 'multi_agent',
    agent_count INTEGER DEFAULT 5,
    coordination_confidence VARCHAR(20),
    agent_conflicts_resolved INTEGER DEFAULT 0,
    language_detected VARCHAR(10)
  );
  `;
  validationResults.database.tables_created.push('llm_analysis');
}

if (missingTables.includes('calls')) {
  createTableSQL += `
  CREATE TABLE IF NOT EXISTS public.calls (
    id SERIAL PRIMARY KEY,
    callid VARCHAR(100) UNIQUE NOT NULL,
    recording_url VARCHAR(500),
    billsec INTEGER,
    processed BOOLEAN DEFAULT FALSE,
    skip BOOLEAN DEFAULT FALSE,
    skip_reason VARCHAR(255),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
  );
  `;
  validationResults.database.tables_created.push('calls');
}

if (missingTables.includes('pipe_response')) {
  createTableSQL += `
  CREATE TABLE IF NOT EXISTS public.pipe_response (
    id SERIAL PRIMARY KEY,
    callid VARCHAR(100) UNIQUE NOT NULL,
    transcript_s3_url VARCHAR(500),
    analysis_s3_url VARCHAR(500),
    llm_processed BOOLEAN DEFAULT FALSE,
    llm_error TEXT,
    stt_error TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
  );
  `;
  validationResults.database.tables_created.push('pipe_response');
}

if (missingTables.includes('agent_results')) {
  createTableSQL += `
  CREATE TABLE IF NOT EXISTS public.agent_results (
    id SERIAL PRIMARY KEY,
    callid VARCHAR(100) NOT NULL,
    agent_type VARCHAR(50) NOT NULL,
    agent_result JSONB,
    processing_time_ms INTEGER,
    error_occurred BOOLEAN DEFAULT FALSE,
    error_message TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT unique_call_agent UNIQUE (callid, agent_type)
  );
  `;
  validationResults.database.tables_created.push('agent_results');
}

return [{
  json: {
    missingTables,
    existingTables,
    createTableSQL,
    validationResults
  }
}];

// Check for errors in the previous node
const error = $input.first()?.error;

// Update validation results
const validationResults = $node['Table Existence Processing'].json.validationResults;

if (error) {
  validationResults.database.errors.push({
    message: error.message,
    timestamp: new Date().toISOString()
  });
  console.log(`❌ Error creating tables: ${error.message}`);
} else {
  console.log(`✅ Successfully created missing tables: ${$node['Table Existence Processing'].json.missingTables.join(', ')}`);
}

return [{
  json: {
    validationResults,
    existingTables: $node['Table Existence Processing'].json.existingTables
  }
}];

// Get existing columns
const existingColumns = $input.all().map(item => item.json.column_name);

// Define required columns for llm_analysis
const requiredColumns = [
  'id', 'callid', 'sentiment', 'topic', 'significant_term', 'general_value',
  'general_experience', 'email_inquired', 'positive_comment_passed_sale',
  'negative_comment_passed_sale', 'price_negotiated', 'customer_addressed_politely',
  'conversation_fun', 'service_advantages_mentioned', 'other_platforms_mentioned',
  'sale_outcome', 'sale_value_scale', 'asked_if_commenters_known',
  'high_profile_advantages_mentioned', 'llm_error_message', 'created_at',
  'updated_at', 'analysis_method', 'agent_count', 'coordination_confidence',
  'agent_conflicts_resolved', 'language_detected'
];

// Find missing columns
const missingColumns = requiredColumns.filter(col => !existingColumns.includes(col));

// Generate SQL to add missing columns
let alterTableSQL = '';

if (missingColumns.includes('coordination_confidence')) {
  alterTableSQL += `ALTER TABLE public.llm_analysis ADD COLUMN IF NOT EXISTS coordination_confidence VARCHAR(20);\n`;
}

if (missingColumns.includes('agent_conflicts_resolved')) {
  alterTableSQL += `ALTER TABLE public.llm_analysis ADD COLUMN IF NOT EXISTS agent_conflicts_resolved INTEGER DEFAULT 0;\n`;
}

if (missingColumns.includes('language_detected')) {
  alterTableSQL += `ALTER TABLE public.llm_analysis ADD COLUMN IF NOT EXISTS language_detected VARCHAR(10);\n`;
}

// Check for other missing columns and add them with appropriate data types
missingColumns.forEach(col => {
  if (!['coordination_confidence', 'agent_conflicts_resolved', 'language_detected'].includes(col)) {
    let dataType;

    if (['id', 'sale_value_scale', 'agent_count'].includes(col)) {
      dataType = 'INTEGER';
    } else if (['created_at', 'updated_at'].includes(col)) {
      dataType = 'TIMESTAMP DEFAULT CURRENT_TIMESTAMP';
    } else if (['llm_error_message'].includes(col)) {
      dataType = 'TEXT';
    } else {
      dataType = 'VARCHAR(100)';
    }

    alterTableSQL += `ALTER TABLE public.llm_analysis ADD COLUMN IF NOT EXISTS ${col} ${dataType};\n`;
  }
});

// Update validation results
let validationResults;
// Check if Table Creation Error Handling node executed
let tcErrorNode = $("Table Creation Error Handling");
let teProcessNode = $("Table Existence Processing");
if (tcErrorNode && tcErrorNode.json && tcErrorNode.json.validationResults) {
  validationResults = tcErrorNode.json.validationResults;
} else if (teProcessNode && teProcessNode.json && teProcessNode.json.validationResults) {
  validationResults = teProcessNode.json.validationResults;
} else {
  validationResults = null; // Fallback if both nodes missing/unexecuted
}

console.log(`📋 Checking llm_analysis table columns`);
console.log(`📋 Missing columns: ${missingColumns.join(', ') || 'none'}`);

return [{
  json: {
    table: 'llm_analysis',
    existingColumns,
    missingColumns,
    alterTableSQL,
    validationResults
  }
}];

// Get existing columns
const existingColumns = $input.all().map(item => item.json.column_name);

// Define required columns for calls
const requiredColumns = [
  'id', 'callid', 'recording_url', 'billsec', 'processed', 'skip', 
  'skip_reason', 'created_at', 'updated_at'
];

// Find missing columns
const missingColumns = requiredColumns.filter(col => !existingColumns.includes(col));

// Generate SQL to add missing columns
let alterTableSQL = '';

// Ensure extension for UUID generation exists
if (missingColumns.includes('id')) {
  alterTableSQL += `CREATE EXTENSION IF NOT EXISTS "pgcrypto";\n`;
}

if (missingColumns.includes('skip')) {
  alterTableSQL += `ALTER TABLE public.calls ADD COLUMN IF NOT EXISTS skip BOOLEAN DEFAULT FALSE;\n`;
}

if (missingColumns.includes('skip_reason')) {
  alterTableSQL += `ALTER TABLE public.calls ADD COLUMN IF NOT EXISTS skip_reason VARCHAR(255);\n`;
}

// Check for other missing columns and add them with appropriate data types
missingColumns.forEach(col => {
  if (!['skip', 'skip_reason'].includes(col)) {
    let dataType;

    if (col === 'id') {
      dataType = 'UUID PRIMARY KEY DEFAULT gen_random_uuid()';
    } else if (col === 'billsec') {
      dataType = 'INTEGER';
    } else if (col === 'processed') {
      dataType = 'BOOLEAN DEFAULT FALSE';
    } else if (['created_at', 'updated_at'].includes(col)) {
      dataType = 'TIMESTAMP DEFAULT CURRENT_TIMESTAMP';
    } else {
      dataType = 'VARCHAR(500)';
    }

    alterTableSQL += `ALTER TABLE public.calls ADD COLUMN IF NOT EXISTS ${col} ${dataType};\n`;
  }
});

// Update validation results
const validationResults = $node['llm_analysis Column Processing'].json.validationResults;

console.log(`📋 Checking calls table columns`);
console.log(`📋 Missing columns: ${missingColumns.join(', ') || 'none'}`);

return [{
  json: {
    table: 'calls',
    existingColumns,
    missingColumns,
    alterTableSQL,
    validationResults,
    previousAlterSQL: $node['llm_analysis Column Processing'].json.alterTableSQL
  }
}];

// Get existing columns
const existingColumns = $input.all().map(item => item.json.column_name);

// Define required columns for pipe_response
const requiredColumns = [
  'id', 'callid', 'transcript_s3_url', 'analysis_s3_url', 'llm_processed',
  'llm_error', 'stt_error', 'created_at', 'updated_at'
];

// Find missing columns
const missingColumns = requiredColumns.filter(col => !existingColumns.includes(col));

// Generate SQL to add missing columns
let alterTableSQL = '';

if (missingColumns.includes('llm_error')) {
  alterTableSQL += `ALTER TABLE public.pipe_response ADD COLUMN IF NOT EXISTS llm_error TEXT;\n`;
}

if (missingColumns.includes('stt_error')) {
  alterTableSQL += `ALTER TABLE public.pipe_response ADD COLUMN IF NOT EXISTS stt_error TEXT;\n`;
}

// Check for other missing columns and add them with appropriate data types
missingColumns.forEach(col => {
  if (!['llm_error', 'stt_error'].includes(col)) {
    let dataType;

    if (['id'].includes(col)) {
      dataType = 'INTEGER';
    } else if (['llm_processed'].includes(col)) {
      dataType = 'BOOLEAN DEFAULT FALSE';
    } else if (['created_at', 'updated_at'].includes(col)) {
      dataType = 'TIMESTAMP DEFAULT CURRENT_TIMESTAMP';
    } else {
      dataType = 'VARCHAR(500)';
    }

    alterTableSQL += `ALTER TABLE public.pipe_response ADD COLUMN IF NOT EXISTS ${col} ${dataType};\n`;
  }
});

// Update validation results
const validationResults = $node['calls Column Processing'].json.validationResults;

console.log(`📋 Checking pipe_response table columns`);
console.log(`📋 Missing columns: ${missingColumns.join(', ') || 'none'}`);

return [{
  json: {
    table: 'pipe_response',
    existingColumns,
    missingColumns,
    alterTableSQL,
    validationResults,
    previousAlterSQL: $node['calls Column Processing'].json.previousAlterSQL + $node['calls Column Processing'].json.alterTableSQL
  }
}];

// Get existing columns
const existingColumns = $input.all().map(item => item.json.column_name);

// Define required columns for agent_results
const requiredColumns = [
  'id', 'callid', 'agent_type', 'agent_result', 'processing_time_ms',
  'error_occurred', 'error_message', 'created_at'
];

// Find missing columns
const missingColumns = requiredColumns.filter(col => !existingColumns.includes(col));

// Generate SQL to add missing columns
let alterTableSQL = '';

if (missingColumns.includes('error_occurred')) {
  alterTableSQL += `ALTER TABLE public.agent_results ADD COLUMN IF NOT EXISTS error_occurred BOOLEAN DEFAULT FALSE;\n`;
}

if (missingColumns.includes('error_message')) {
  alterTableSQL += `ALTER TABLE public.agent_results ADD COLUMN IF NOT EXISTS error_message TEXT;\n`;
}

// Check for other missing columns and add them with appropriate data types
missingColumns.forEach(col => {
  if (!['error_occurred', 'error_message'].includes(col)) {
    let dataType;

    if (['id', 'processing_time_ms'].includes(col)) {
      dataType = 'INTEGER';
    } else if (['agent_result'].includes(col)) {
      dataType = 'JSONB';
    } else if (['created_at'].includes(col)) {
      dataType = 'TIMESTAMP DEFAULT CURRENT_TIMESTAMP';
    } else {
      dataType = 'VARCHAR(100)';
    }

    alterTableSQL += `ALTER TABLE public.agent_results ADD COLUMN IF NOT EXISTS ${col} ${dataType};\n`;
  }
});

// Combine all alter table SQL statements
const combinedAlterSQL = $node['pipe_response Column Processing'].json.previousAlterSQL + 
                        $node['pipe_response Column Processing'].json.alterTableSQL + 
                        alterTableSQL;

// Update validation results
const validationResults = $node['pipe_response Column Processing'].json.validationResults;

// Check if we have any columns to add
const hasColumnsToAdd = combinedAlterSQL.trim().length > 0;

console.log(`📋 Checking agent_results table columns`);
console.log(`📋 Missing columns: ${missingColumns.join(', ') || 'none'}`);

return [{
  json: {
    hasColumnsToAdd,
    combinedAlterSQL,
    validationResults
  }
}];

// Check for errors in the previous node
const error = $input.first()?.error;

// Update validation results
const validationResults = $('agent_results Column Processing').first().json.validationResults;

if (error) {
  validationResults.database.errors.push({
    message: `Column addition error: ${error.message}`,
    timestamp: new Date().toISOString()
  });
  console.log(`❌ Error adding columns: ${error.message}`);
} else {
  console.log(`✅ Successfully added missing columns to tables`);
}

return [{
  json: {
    validationResults
  }
}];

// Check for errors in the previous node
const error = $input.first()?.error;

// Update validation results
let validationResults;
if ($node['Column Addition Error Handling']) {
  validationResults = $node['Column Addition Error Handling'].json.validationResults;
} else if ($node['agent_results Column Processing']) {
  validationResults = $node['agent_results Column Processing'].json.validationResults;
} else {
  validationResults = $node['Table Existence Processing'].json.validationResults;
}

if (error) {
  // Bucket doesn't exist or access denied
  validationResults.s3.errors.push({
    message: `Bucket check error: ${error.message}`,
    timestamp: new Date().toISOString()
  });
  validationResults.s3.bucket_exists = false;
  console.log(`❌ S3 bucket 'callintech' check failed: ${error.message}`);
} else {
  // Bucket exists
  validationResults.s3.bucket_exists = true;
  console.log(`✅ S3 bucket 'callintech' exists`);
}

return [{
  json: {
    validationResults,
    bucketExists: validationResults.s3.bucket_exists
  }
}];

// Check for errors in the previous node
const error = $input.first()?.error;

// Update validation results
const validationResults = $node['S3 Bucket Existence Processing'].json.validationResults;

if (error) {
  validationResults.s3.errors.push({
    message: `Bucket creation error: ${error.message}`,
    timestamp: new Date().toISOString()
  });
  console.log(`❌ Error creating S3 bucket 'callintech': ${error.message}`);
} else {
  validationResults.s3.bucket_exists = true;
  console.log(`✅ Successfully created S3 bucket 'callintech'`);
}

return [{
  json: {
    validationResults
  }
}];

// Get existing folders from previous node
const s3Objects = $input.all().map(item => item.json);

// Extract folder names (objects ending with '/')
const existingFolders = s3Objects
  .filter(obj => obj.Key && obj.Key.endsWith('/'))
  .map(obj => obj.Key);

// Define required folders
const requiredFolders = [
  'recordings/',
  'transcripts/',
  'analysis/',
  'agent_results/'
];

// Find missing folders
const missingFolders = requiredFolders.filter(folder => !existingFolders.includes(folder));

// Update validation results
let validationResults;
if ($node['S3 Bucket Creation Error Handling']) {
  validationResults = $node['S3 Bucket Creation Error Handling'].json.validationResults;
} else {
  validationResults = $node['S3 Bucket Existence Processing'].json.validationResults;
}

validationResults.s3.folders_checked = requiredFolders;

console.log(`📁 Existing folders: ${existingFolders.join(', ') || 'none'}`);
console.log(`📁 Missing folders: ${missingFolders.join(', ') || 'none'}`);

return [{
  json: {
    existingFolders,
    missingFolders,
    validationResults
  }
}];

// Check for errors in the previous node
const error = $input.first()?.error;
const folder = $input.first()?.json;

// Update validation results
const validationResults = $node['S3 Folder Structure Processing'].json.validationResults;

if (error) {
  validationResults.s3.errors.push({
    folder,
    message: `Folder creation error: ${error.message}`,
    timestamp: new Date().toISOString()
  });
  console.log(`❌ Error creating S3 folder '${folder}': ${error.message}`);
} else {
  validationResults.s3.folders_created.push(folder);
  console.log(`✅ Successfully created S3 folder '${folder}'`);
}

return [{
  json: {
    folder,
    validationResults
  }
}];

// Get the latest validation results
let validationResults;

if ($node['Wait for All Folder Creations']) {
  // If we created folders, get results from there
  const folderResults = $input.all();
  validationResults = folderResults[folderResults.length - 1].json.validationResults;
} else if ($node['S3 Folder Structure Processing']) {
  // If we didn't need to create folders
  validationResults = $node['S3 Folder Structure Processing'].json.validationResults;
} else {
  // Fallback
  validationResults = $node['S3 Bucket Existence Processing'].json.validationResults;
}

// Calculate overall validation status
const dbErrors = validationResults.database.errors.length;
const s3Errors = validationResults.s3.errors.length;
const totalErrors = dbErrors + s3Errors;

const dbTablesCreated = validationResults.database.tables_created.length;
const s3FoldersCreated = validationResults.s3.folders_created.length;
const totalCreated = dbTablesCreated + s3FoldersCreated;

const validationStatus = totalErrors === 0 ? 'success' : 'warning';

// Generate summary
const summary = {
  timestamp: new Date().toISOString(),
  status: validationStatus,
  database: {
    tables_checked: validationResults.database.tables_checked,
    tables_created: validationResults.database.tables_created,
    columns_added: validationResults.database.columns_added || [],
    errors: validationResults.database.errors
  },
  s3: {
    bucket_exists: validationResults.s3.bucket_exists,
    folders_checked: validationResults.s3.folders_checked,
    folders_created: validationResults.s3.folders_created,
    errors: validationResults.s3.errors
  },
  total_errors: totalErrors,
  total_created: totalCreated
};

console.log(`🔄 Infrastructure Setup and Validation Workflow completed with status: ${validationStatus}`);
console.log(`📊 Summary: ${totalCreated} resources created, ${totalErrors} errors encountered`);

return [{
  json: {
    summary
  }
}];

// Get summary from previous node
const { summary } = $input.first().json;

// Format a detailed report
const report = `
# Infrastructure Setup and Validation Report

## Summary
- **Timestamp:** ${summary.timestamp}
- **Status:** ${summary.status.toUpperCase()}
- **Total Resources Created:** ${summary.total_created}
- **Total Errors:** ${summary.total_errors}

## Database Validation
- **Tables Checked:** ${summary.database.tables_checked.join(', ')}
- **Tables Created:** ${summary.database.tables_created.length > 0 ? summary.database.tables_created.join(', ') : 'None'}
- **Columns Added:** ${summary.database.columns_added.length > 0 ? summary.database.columns_added.join(', ') : 'None'}
- **Errors:** ${summary.database.errors.length > 0 ? JSON.stringify(summary.database.errors, null, 2) : 'None'}

## S3 Validation
- **Bucket Exists:** ${summary.s3.bucket_exists ? 'Yes' : 'No'}
- **Folders Checked:** ${summary.s3.folders_checked.join(', ')}
- **Folders Created:** ${summary.s3.folders_created.length > 0 ? summary.s3.folders_created.join(', ') : 'None'}
- **Errors:** ${summary.s3.errors.length > 0 ? JSON.stringify(summary.s3.errors, null, 2) : 'None'}
`;

console.log('📝 Generated validation report');

return [{
  json: {
    report,
    summary
  }
}];

// Get report from previous node
const { report, summary } = $input.first().json;

// Format error notification
const errorNotification = {
  subject: `⚠️ Infrastructure Setup Completed with Warnings - ${new Date().toISOString()}`,
  body: `
  Infrastructure setup completed with ${summary.total_errors} warnings.

  Please review the full report for details.
  `
};

console.log(`📧 Would send warning notification: ${errorNotification.subject}`);

return [{
  json: {
    report,
    summary,
    notification: errorNotification
  }
}];

// Get report from previous node
const { report, summary } = $input.first().json;

// Format success notification
const successNotification = {
  subject: `✅ Infrastructure Setup Completed Successfully - ${new Date().toISOString()}`,
  body: `
  Infrastructure setup completed successfully.

  Resources created: ${summary.total_created}
  `
};

console.log(`📧 Would send success notification: ${successNotification.subject}`);

return [{
  json: {
    report,
    summary,
    notification: successNotification
  }
}];

// Get notification from previous node
const { report, notification } = $input.first().json;

console.log(`✅ Infrastructure Setup and Validation Workflow completed`);
console.log(`📊 Report: ${report}`);

return [{
  json: {
    workflow_status: 'completed',
    completion_timestamp: new Date().toISOString(),
    report
  }
}];
